"""Plumbing demo for V5 with SYNTHETIC node data (generated by the team, D3/D4). Proves code, not hardware."""
import dataclasses, random
from ..weather.scenarios import SyntheticScenario
from .bias import NodeObs, v5_bias_test, estimate_bias


def synthetic_node(hours, offset_c=2.5, noise_c=0.4, seed=1):
    rng = random.Random(seed)
    return [NodeObs(h.time_iso, round(h.tdb_c + offset_c + rng.uniform(-noise_c, noise_c), 2), h.rh_pct, None, 90.0) for h in hours]


if __name__ == "__main__":
    # two synthetic days laid end to end so there are enough paired hours
    d1 = SyntheticScenario("hot_humid", "2026-01-01").hours(); d2 = SyntheticScenario("hot_humid", "2026-01-02").hours()
    fc = d1 + d2
    print("SYNTHETIC data, plumbing only.")
    print(v5_bias_test(fc, synthetic_node(fc)))
    print("cooler site (-2.5 C):", estimate_bias(fc, synthetic_node(fc, -2.5)))
